  `vatnum` mediumtext,
  `email` varchar(155) DEFAULT NULL,
  `idnumber` varchar(45) DEFAULT NULL,
  `employer` varchar(145) DEFAULT NULL,
  `supplierId` bigint DEFAULT NULL,
  `clientscol` varchar(45) DEFAULT NULL,
