CREATE TABLE `debitnotes` (
  `recnum` int NOT NULL AUTO_INCREMENT,
  `sid` int DEFAULT NULL,
  `piid` int DEFAULT NULL,
  `name` varchar(100) DEFAULT NULL,
  `telephone` varchar(20) DEFAULT NULL,
  `cellphone` varchar(20) DEFAULT NULL,
  `fax` varchar(20) DEFAULT NULL,
  `postaladdress` varchar(255) DEFAULT NULL,
  `physicaladdress` varchar(255) DEFAULT NULL,
  `vatnum` varchar(100) DEFAULT NULL,
  `notedate` date DEFAULT NULL,
  `amount` decimal(13,2) DEFAULT NULL,
  `notes` text,
  `uk` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`recnum`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;
