  `receiptdate` date DEFAULT NULL,
  `cid` varchar(20) DEFAULT NULL,
  `name` varchar(155) DEFAULT NULL,
  `surname` varchar(155) DEFAULT NULL,
  `telephone` varchar(20) DEFAULT NULL,
  `cellphone` varchar(20) DEFAULT NULL,
  `fax` varchar(20) DEFAULT NULL,
  `postaladdress` varchar(155) DEFAULT NULL,
  `physicaladdress` varchar(155) DEFAULT NULL,
  `recurring` varchar(10) DEFAULT NULL,
  `AmountDue` decimal(10,2) DEFAULT NULL,
  `received` decimal(10,2) DEFAULT NULL,
  `changeIssued` decimal(10,2) DEFAULT NULL,
  `outstanding` decimal(10,2) DEFAULT NULL,
  `uk` varchar(50) DEFAULT NULL,
  `orgid` varchar(50) DEFAULT NULL,
  `InvoiceNumber` int unsigned DEFAULT NULL,
  `email` varchar(45) DEFAULT NULL,
  `cashPayment` varchar(10) DEFAULT NULL,
  `taxAmount` decimal(10,0) DEFAULT NULL,
  PRIMARY KEY (`recnum`)
) ENGINE=InnoDB AUTO_INCREMENT=255 DEFAULT CHARSET=latin1;
